class Coach
  class CoachError < RuntimeError; end

  include HTTParty
  format  :json
  # TODO: Are we going to have different username/password for
  # coaches in different regions?
  basic_auth ENV['COACH_USERNAME'], ENV['COACH_PASSWORD']

  attr_reader :box, :coach_uri

  def initialize(box)
    @box = box
    @coach_uri = @box.region.coach_uri
  end

  def provision_box
    # Get public keys from the ones generated by the box
    # as well as the ones uploaded by the user
    public_keys = @box.key_pairs.map(&:public_key) +
                  @box.owner.public_keys.map(&:key)

    box_hash = {
      name: self.box.name,
      id: self.box.id,
      runtime: self.box.box_template.runtime,
      # This is hard-coded for now
      memory: '256M',
      disk_space: '1G'
    }

    if public_keys.present?
      box_hash.merge!(public_keys: public_keys.to_json)
    end

    result = self.class.post "#{self.coach_uri}/boxes", query: { box: box_hash }

    render(result)
  end

  def start_box
    result = self.class.put "#{self.coach_uri}/boxes/#{self.box.container_name}/start",
                            query: { box: { boxer_id: self.box.host } },
                            headers: { 'Content-Length' => '0' }

    render(result)
  end

  def stop_box
    result = self.class.put "#{self.coach_uri}/boxes/#{self.box.container_name}/stop",
                            query: { box: { boxer_id: self.box.host } },
                            headers: { 'Content-Length' => '0' }

    render(result)
  end

  def restart_box
    result = self.class.put "#{self.coach_uri}/boxes/#{self.box.container_name}/restart",
                            query: { box: { boxer_id: self.box.host } },
                            headers: { 'Content-Length' => '0' }

    render(result)
  end

  def terminate_box
    result = self.class.put "#{self.coach_uri}/boxes/#{self.box.container_name}/destroy",
                            query: { box: { boxer_id: self.box.host } },
                            headers: { 'Content-Length' => '0' }

    render(result)
  end

  def snapshot_box
    result = self.class.put "#{self.coach_uri}/boxes/#{self.box.container_name}/snapshot",
                            query: { box: { boxer_id: self.box.host } },
                            headers: { 'Content-Length' => '0' }

    render(result)
  end

  def add_public_key(key)
    result = self.class.put "#{self.coach_uri}/boxes/#{self.box.container_name}",
                            query: {
                              box: {
                                boxer_id: self.box.host,
                                data_type: 'aio:configure:add_public_key',
                                data: key
                              }
                            },
                            headers: { 'Content-Length' => '0' }

    render(result)
  end

  def remove_public_key(key)
    result = self.class.put "#{self.coach_uri}/boxes/#{self.box.container_name}",
                            query: {
                              box: {
                                boxer_id: self.box.host,
                                data_type: 'aio:configure:remove_public_key',
                                data: key
                              }
                            },
                            headers: { 'Content-Length' => '0' }
    render(result)
  end

  private
  def render(result)
    if result['status'] == 'OK'
      return true
    else
      raise CoachError, "#{result['status']}: #{result['text']}"
    end
  end
end
